fn epsilon_gaussian(orders:&[f64],sigma:f64,steps:u64,delta:f64)->Result<(f64,f64),String>{if sigma<=0.0||steps==0||!(0.0..1.0).contains(&delta){return Err("require sigma>0, steps>0, delta in (0,1)".into())}let mut best=(f64::INFINITY,0.0);for &a in orders{if a<=1.0{return Err("Renyi orders must exceed 1".into())}let rdp=steps as f64*a/(2.0*sigma*sigma);let eps=rdp+(-delta.ln())/(a-1.0);if eps<best.0{best=(eps,a)}}Ok(best)}
fn main(){let orders:Vec<f64>=(2..=128).map(|x|x as f64).collect();match epsilon_gaussian(&orders,1.2,10000,1e-6){Ok((e,a))=>println!("epsilon={e:.6} minimizing_order={a}"),Err(e)=>{eprintln!("{e}");std::process::exit(2)}}}
